<?php require __DIR__.'/../includes/functions.php'; admin_required(); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){foreach(['site_name','email','phone'] as $k){$st=$pdo->prepare('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)');$st->execute([$k,$_POST[$k]??'']);}$msg='Saved.';} ?><!doctype html><html><head><meta charset="utf-8"><title>Settings</title><link rel="stylesheet" href="admin.css"></head><body><div class="top"><div class="wrap"><b>Settings</b><a href="index.php" style="color:#fff">← Admin</a></div></div><div class="wrap" style="padding:30px 0"><div class="card"><h2>Site settings</h2><?php if($msg):?><p><?=e($msg)?></p><?php endif;?><form method="post"><label>Site name</label><input name="site_name" value="<?=e(setting('site_name'))?>"><label>Email</label><input name="email" value="<?=e(setting('email'))?>"><label>Phone</label><input name="phone" value="<?=e(setting('phone'))?>"><button class="button">Save</button></form></div></div></body></html>
